package dev.pocketengine.browser;

import dev.pocketengine.store.TaskStore;
import java.net.URI;
import java.util.Set;
import org.json.JSONArray;
import org.json.JSONObject;

/** Fixed read-only table/list schema recipe, not JavaScript, a permission or a cache of website facts. */
public final class BrowserReadRecipe {
    public static final String RESOURCE="references/browser-read.json",FORMAT="pocketworld.browser-read-recipe.v1";
    private BrowserReadRecipe() { }
    public static JSONObject referenceSchema()throws Exception {return new JSONObject().put("type","object").put("additionalProperties",false).put("required",new JSONArray().put("id").put("revision").put("digest")).put("properties",new JSONObject().put("id",new JSONObject().put("type","string").put("maxLength",36)).put("revision",new JSONObject().put("type","integer").put("minimum",1)).put("digest",new JSONObject().put("type","string").put("maxLength",64)));}
    public static void reference(JSONObject ref)throws Exception {if(ref.length()!=3)throw new IllegalArgumentException("读取配方只接受精确版本引用");BrowserTaskSpace.uuid(ref.getString("id"));if(!(ref.get("revision") instanceof Number)||ref.getInt("revision")<1||!ref.getString("digest").matches("[a-f0-9]{64}"))throw new IllegalArgumentException("读取配方版本无效");}
    /** Native owner derivation from a real saved, complete delivered projection; never model-created authority. */
    public static JSONObject fromSource(JSONObject source,String query)throws Exception {
        if(!source.getString("kind").equals(BrowserSemanticRead.KIND)||!source.has("structuredProjection"))throw new IllegalArgumentException("请先保留一份实际读取的表格或列表依据");JSONObject projection=source.getJSONObject("structuredProjection");BrowserStructuredSource.validate(projection);if(projection.getBoolean("partial"))throw new IllegalArgumentException("这份来源仍有缺失，请先缩小区域并保存完整结构后再制作配方");
        String literal=query==null?"":query.trim();if(literal.isEmpty()||literal.length()>160)throw new IllegalArgumentException("请填写1–160字的区域识别词；只作字面匹配，不是脚本");URI u=new URI(source.getString("privateUrl"));String origin=BrowserFrameOrigins.exact(new URI(u.getScheme(),null,u.getHost(),u.getPort(),null,null,null).toASCIIString());String mode=projection.getString("mode");JSONArray columns=new JSONArray(),headers=new JSONArray();
        if(mode.equals("table")){JSONArray rows=projection.getJSONArray("data");for(int i=0;i<rows.length()&&headers.length()==0;i++){JSONArray cells=rows.getJSONObject(i).getJSONArray("cells");for(int j=0;j<cells.length();j++){JSONObject cell=cells.getJSONObject(j);if(cell.getString("role").equals("columnheader")){String text=cell.getString("text");if(text.isEmpty()||text.length()>160||cell.getInt("colSpan")!=1||cell.getInt("rowSpan")!=1)throw new IllegalArgumentException("表头缺失、过长或跨行列，暂不能制作这个固定列配方");headers.put(new JSONObject().put("column",cell.getInt("column")).put("text",text));}}}if(headers.length()==0||headers.length()>12)throw new IllegalArgumentException("读取配方需要1–12个真实单列表头");for(int i=0;i<headers.length();i++)columns.put(new JSONObject().put("name","column_"+headers.getJSONObject(i).getInt("column")).put("column",headers.getJSONObject(i).getInt("column")).put("type","string"));}
        else columns.put(new JSONObject().put("name","itemText").put("column",0).put("type","string"));
        JSONObject recipe=new JSONObject().put("format",FORMAT).put("version",1).put("mode",mode).put("query",literal).put("profileId",source.getString("profileId")).put("origin",origin).put("path",u.getRawPath()==null?"":u.getRawPath())
                .put("inputSchema",new JSONObject().put("type","object").put("properties",new JSONObject()).put("additionalProperties",false)).put("outputFields",columns).put("expectedHeaders",headers).put("deadlineMs",8000).put("maxOutputBytes",8192)
                .put("createdFrom",new JSONObject().put("sourceRef",BrowserResearchResult.reference(source.getString("taskId"),source.getString("sourceId"))).put("structuredRevision",projection.getString("revision")))
                .put("readOnly",true).put("grantsAdded",new JSONArray()).put("cachedFacts",false);
        validate(recipe);return recipe;
    }
    public static void validate(JSONObject r)throws Exception {
        Set<String> fields=Set.of("format","version","mode","query","profileId","origin","path","inputSchema","outputFields","expectedHeaders","deadlineMs","maxOutputBytes","createdFrom","readOnly","grantsAdded","cachedFacts");if(r.length()!=fields.size())throw new SecurityException("读取配方字段不完整");for(var it=r.keys();it.hasNext();)if(!fields.contains(it.next()))throw new SecurityException("读取配方包含写动作或额外权限字段");
        if(!r.getString("format").equals(FORMAT)||r.getInt("version")!=1||!Set.of("table","list").contains(r.getString("mode"))||r.getString("query").isEmpty()||r.getString("query").length()>160||!r.getString("profileId").matches("[A-Za-z0-9_-]{1,80}")||!r.getString("origin").equals(BrowserFrameOrigins.exact(r.getString("origin")))||!Boolean.TRUE.equals(r.get("readOnly"))||!Boolean.FALSE.equals(r.get("cachedFacts"))||r.getJSONArray("grantsAdded").length()!=0||r.getInt("deadlineMs")!=8000||r.getInt("maxOutputBytes")!=8192)throw new SecurityException("配方不是固定范围只读配置");
        String path=r.getString("path");URI u=new URI(r.getString("origin")+path);if(path.length()>2048||!path.isEmpty()&&!path.startsWith("/")||u.getRawQuery()!=null||u.getRawFragment()!=null||!u.getRawPath().equals(path))throw new SecurityException("读取配方路径无效");
        JSONObject input=r.getJSONObject("inputSchema");if(input.length()!=3||!input.getString("type").equals("object")||input.getJSONObject("properties").length()!=0||!Boolean.FALSE.equals(input.get("additionalProperties")))throw new SecurityException("配方不接受额外上下文输入");
        JSONArray output=r.getJSONArray("outputFields"),headers=r.getJSONArray("expectedHeaders");if(output.length()<1||output.length()>12||headers.length()>12||r.getString("mode").equals("table")&&(headers.length()==0||headers.length()!=output.length())||r.getString("mode").equals("list")&&(headers.length()!=0||output.length()!=1))throw new SecurityException("配方表头或输出列无效");Set<String> names=new java.util.HashSet<>();Set<Integer> positions=new java.util.HashSet<>();for(int i=0;i<output.length();i++){JSONObject f=output.getJSONObject(i);if(f.length()!=3||!f.getString("name").matches("itemText|column_[0-9]{1,2}")||!names.add(f.getString("name"))||!positions.add(f.getInt("column"))||f.getInt("column")<0||f.getInt("column")>23||!(r.getString("mode").equals("list")?f.getString("name").equals("itemText")&&f.getInt("column")==0:f.getString("name").equals("column_"+f.getInt("column")))||!f.getString("type").equals("string"))throw new SecurityException("配方输出不是逐字单元格字段");}
        for(int i=0;i<headers.length();i++){JSONObject h=headers.getJSONObject(i);if(h.length()!=2||!positions.contains(h.getInt("column"))||h.getString("text").isEmpty()||h.getString("text").length()>160)throw new SecurityException("配方前态表头无效");}JSONObject source=r.getJSONObject("createdFrom");if(source.length()!=2||!source.getString("sourceRef").matches("task:[a-f0-9-]{36}:browser-source:[a-f0-9-]{36}")||!source.getString("structuredRevision").matches("[a-f0-9]{64}"))throw new SecurityException("配方缺少实际来源谱系");if(r.toString().length()>10000)throw new SecurityException("读取配方超出限额");
    }
    public static void matchesRequest(JSONObject r,JSONObject read)throws Exception {validate(r);BrowserSemanticRead.validate(read);if(!read.getString("mode").equals(r.getString("mode"))||!read.optString("query").equals(r.getString("query"))||read.has("cursor")||read.has("regionRef")||read.has("baseRevision"))throw new IllegalArgumentException("此配方只接受其固定mode/query和当前明确frameRef，不接受旧区域、续读或额外输入");}
    public static void pagePrecondition(JSONObject r,String profileId,String actualOrigin,String url,boolean child)throws Exception {validate(r);if(!profileId.equals(r.getString("profileId"))||!actualOrigin.equals(r.getString("origin")))throw new SecurityException("读取配方不属于当前登录资料或已准来源，未改为跨源读取");if(!child&&!pathMatches(r,url))throw new IllegalArgumentException("当前页面路径与读取配方不同，请普通observe重新探索；未自动导航");}
    private static boolean pathMatches(JSONObject r,String url)throws Exception {URI u=new URI(url);return u.getHost()!=null&&u.getUserInfo()==null&&r.getString("origin").equals(BrowserFrameOrigins.exact(new URI(u.getScheme(),null,u.getHost(),u.getPort(),null,null,null).toASCIIString()))&&r.getString("path").equals(u.getRawPath()==null?"":u.getRawPath());}
    /** One existing observe result, no retry/navigation. A drift returns its real ordinary observation. */
    public static JSONObject project(JSONObject r,JSONObject ref,JSONObject observed)throws Exception {
        validate(r);reference(ref);JSONObject result=new JSONObject(observed.toString());String reason="";JSONObject read=result.optJSONObject("read");
        if(!result.optString("status").equals("observed")||read==null)reason="observation_unavailable";
        else if(!pathMatches(r,result.getString("url")))reason="page_path_changed";
        else if(!read.getString("mode").equals(r.getString("mode"))||read.getJSONObject("facts").getBoolean("partial"))reason="coverage_or_structure_changed";
        JSONArray rows=new JSONArray();if(reason.isEmpty()){
            JSONArray data=read.getJSONArray("data"),expected=r.getJSONArray("expectedHeaders");boolean foundHeader=expected.length()==0;
            for(int i=0;i<data.length();i++){JSONObject row=data.getJSONObject(i);if(r.getString("mode").equals("table")){JSONArray cells=row.getJSONArray("cells");boolean all=true;for(int h=0;h<expected.length();h++){JSONObject wanted=expected.getJSONObject(h);boolean present=false;for(int c=0;c<cells.length();c++){JSONObject cell=cells.getJSONObject(c);if(cell.getInt("column")==wanted.getInt("column")&&cell.getString("role").equals("columnheader")&&cell.getString("text").equals(wanted.getString("text"))&&cell.getInt("colSpan")==1&&cell.getInt("rowSpan")==1&&!cell.getBoolean("partial"))present=true;}all&=present;}if(all&&expected.length()>0){foundHeader=true;continue;}}
                JSONObject values=new JSONObject();JSONArray fields=r.getJSONArray("outputFields");for(int f=0;f<fields.length();f++){JSONObject field=fields.getJSONObject(f);String text=null;if(r.getString("mode").equals("list")){if(!row.getBoolean("partial"))text=row.getString("text");}else{JSONArray cells=row.getJSONArray("cells");for(int c=0;c<cells.length();c++){JSONObject cell=cells.getJSONObject(c);if(cell.getInt("column")==field.getInt("column")&&!cell.getBoolean("partial")&&cell.getInt("colSpan")==1&&cell.getInt("rowSpan")==1)text=cell.getString("text");}}if(text==null){reason="output_schema_changed";break;}values.put(field.getString("name"),text);}if(!reason.isEmpty())break;rows.put(new JSONObject().put("sourceRowIndex",row.getInt("index")).put("values",values));
            }
            if(!foundHeader)reason="header_precondition_changed";if(rows.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>8192)reason="recipe_output_budget";
        }
        JSONObject metadata=new JSONObject().put("id",ref.getString("id")).put("revision",ref.getInt("revision")).put("digest",ref.getString("digest")).put("configFingerprint",TaskStore.capabilityFingerprint(r)).put("status",reason.isEmpty()?"matched":"drift").put("reason",reason.isEmpty()?JSONObject.NULL:reason).put("fields",new JSONArray(r.getJSONArray("outputFields").toString())).put("sourceObservationId",result.has("observationId")?result.get("observationId"):JSONObject.NULL).put("ordinaryObserveFallbackRequired",!reason.isEmpty()).put("automaticRetryPerformed",false);
        result.put("readRecipe",metadata);if(reason.isEmpty())result.put("recipeOutput",rows);result.put("message",reason.isEmpty()?"按当前启用的只读配方版本读取到逐字字段；实际覆盖仍见read.facts，配方不授予来源保存或网站写权限。":"读取配方与页面结构/覆盖不再匹配；已返回这次实际普通观察，请在当前授权内重新探索，未导航、重试或重新授权。");
        if(result.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>BrowserSemanticRead.OUTPUT_BYTES){result.remove("recipeOutput");metadata.put("status","drift").put("reason","recipe_output_budget").put("ordinaryObserveFallbackRequired",true);}return result;
    }
    public static void validateEvidence(JSONObject m)throws Exception {Set<String> keys=Set.of("id","revision","digest","configFingerprint","status","reason","fields","sourceObservationId","ordinaryObserveFallbackRequired","automaticRetryPerformed");if(m.length()!=keys.size())throw new SecurityException("读取配方来源字段不完整");for(var it=m.keys();it.hasNext();)if(!keys.contains(it.next()))throw new SecurityException("读取配方来源含额外权限字段");reference(new JSONObject().put("id",m.getString("id")).put("revision",m.getInt("revision")).put("digest",m.getString("digest")));if(!m.getString("configFingerprint").matches("[a-f0-9]{64}")||!Set.of("matched","drift").contains(m.getString("status"))||!Boolean.FALSE.equals(m.get("automaticRetryPerformed"))||m.getBoolean("ordinaryObserveFallbackRequired")!=m.getString("status").equals("drift"))throw new SecurityException("读取配方来源声明无效");if(m.isNull("sourceObservationId")){if(!m.getString("status").equals("drift"))throw new SecurityException("配方缺少实际读取观察");}else BrowserTaskSpace.uuid(m.getString("sourceObservationId"));if(m.getString("status").equals("matched")?!m.isNull("reason"):!Set.of("observation_unavailable","page_path_changed","coverage_or_structure_changed","output_schema_changed","header_precondition_changed","recipe_output_budget","recipe_version_changed").contains(m.getString("reason")))throw new SecurityException("配方漂移原因无效");if(m.getJSONArray("fields").length()<1||m.getJSONArray("fields").length()>12)throw new SecurityException("配方来源字段超限");}
}
